  const getSubtree = (node) => {
    if (!node) return "Not found";
    return node.children.map(c => `${c.name} (${c.type}, id: ${c.id})`).join("\n");
  };

  return `Foundations Page children:\n${getSubtree(fPage)}\n\nComponents Page children:\n${getSubtree(cPage)}\n\nMedia Page children:\n${getSubtree(mPage)}`;
})()

(async () => {
  const fFrame = await figma.getNodeByIdAsync("1:5");
  const cFrame = await figma.getNodeByIdAsync("1:24");
  const mFrame = await figma.getNodeByIdAsync("2:6");

  const dumpTextAndFills = (node) => {
    let res = [];
    if (node.type === "TEXT") {
      res.push(`TEXT: ${node.name} -> "${node.characters}" (Font: ${node.fontName ? node.fontName.family + " " + node.fontName.style : "mixed"}, Size: ${node.fontSize})`);
    } else if (node.type === "RECTANGLE" || node.type === "FRAME" || node.type === "VECTOR" || node.type === "INSTANCE" || node.type === "COMPONENT") {
      res.push(`${node.type}: ${node.name} (id: ${node.id})`);
    }
    if ("children" in node) {
      for (const child of node.children) {
        res.push(...dumpTextAndFills(child));
      }
    }
    return res;
  };

  return `--- Foundations ---\n${dumpTextAndFills(fFrame).join("\n")}\n\n--- Components ---\n${dumpTextAndFills(cFrame).join("\n")}\n\n--- Media ---\n${dumpTextAndFills(mFrame).join("\n")}`;
})()

